struct P *q = &a;
struct P b = a;
q->x = 7;
printf("%d %d\n", a.x, b.x);

struct Node { int value; struct Node *next; };

int main(void) {
    struct Node *head = NULL;
    for (int i = 1; i <= 3; i++) {
        struct Node *n = malloc(sizeof *n);
        n->value = i;
        n->next = head;
        head = n;
    }
    for (struct Node *p = head; p != NULL; p = p->next) {
        printf("%d ", p->value);
    }
    printf("\n");
}
